  10	type UnknownRecord = Record<string, unknown>;
  11	
  12	export type McpJsonNode = UnknownRecord & {
  13		type: string;
  14		children?: McpJsonNode[];
  15	};
  16	
  17	type RendererAction = (...args: unknown[]) => unknown;
  18	
  19	interface RenderContext {
  20		data: UnknownRecord;
  21		actions?: Record<string, RendererAction>;
  22		openLink: (href: string) => void;
  23	}
  24	
  25	function isRecord(value: unknown): value is UnknownRecord {
  26		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
  27	}
  28	
  29	function getValueByPath(value: UnknownRecord, path: string): unknown {
  30		const parts = path.replace(/\[(\d+)\]/g, ".$1").split(".");
  31		let current: unknown = value;
  32		for (const part of parts) {
  33			if (!isRecord(current) && !Array.isArray(current)) return undefined;
  34			current = (current as UnknownRecord)[part];
  35		}
  36		return current;
  37	}
  38	
  39	function stringify(value: unknown): string {
  40		try {
  41			return JSON.stringify(value, null, 2);
  42		} catch {
  43			return String(value);
  44		}
  45	}
  46	
  47	function humanize(value: string): string {
  48		return value
  49			.replace(/[_-]+/g, " ")
  50			.replace(/\b\w/g, (letter) => letter.toUpperCase());
  51	}
  52	
  53	function resolveProp(value: unknown, context: RenderContext): unknown {
  54		if (typeof value !== "string") return value;
  55		if (value.startsWith("@")) return context.actions?.[value.slice(1)];
  56		const exact = value.match(/^\{\{(.+?)\}\}$/);
  57		if (exact) return getValueByPath(context.data, exact[1].trim());
  58		return value.replace(/\{\{(.+?)\}\}/g, (_match, path: string) => {
  59			const resolved = getValueByPath(context.data, path.trim());
  60			return resolved === undefined ? "" : String(resolved);
  61		});
  62	}
  63	
  64	function resolvedProps(
  65		node: McpJsonNode,
  66		context: RenderContext,
  67	): UnknownRecord {
  68		const raw: UnknownRecord = {};
  69		for (const [key, value] of Object.entries(node)) {
  70			if (
  71				!["type", "children", "props", "path", "fallback", "key"].includes(key)
  72			) {
  73				raw[key] = value;
  74			}
  75		}
  76		if (isRecord(node.props)) Object.assign(raw, node.props);
  77		const resolved: UnknownRecord = {};
  78		for (const [key, value] of Object.entries(raw)) {
  79			const next = resolveProp(value, context);
  80			if (/^on[A-Z]/.test(key) && typeof next !== "function") continue;
  81			resolved[key] = next;
  82		}
  83		return resolved;
  84	}
