  86	function domProps(props: UnknownRecord): UnknownRecord {
  87		const result: UnknownRecord = {};
  88		for (const key of [
  89			"className",
  90			"style",
  91			"title",
  92			"id",
  93			"role",
  94			"colSpan",
  95			"rowSpan",
  96			"onClick",
  97		]) {
  98			if (props[key] !== undefined) result[key] = props[key];
  99		}
 100		for (const [key, value] of Object.entries(props)) {
 101			if (key.startsWith("aria-") || key.startsWith("data-")) result[key] = value;
 102		}
 103		return result;
 104	}
