 117	function normalizePoints(
 118		value: unknown,
 119		labelField = "label",
 120		valueField = "value",
 121	): Array<{ key: string; label: string; sourceIndex: number; value: number }> {
 122		if (!Array.isArray(value)) return [];
 123		return value
 124			.map((item, index) => {
 125				if (typeof item === "number")
 126					return {
 127						key: `${index + 1}:${item}`,
 128						label: String(index + 1),
 129						sourceIndex: index,
 130						value: item,
 131					};
 132				if (!isRecord(item)) return null;
 133				const label = String(item[labelField] ?? item.name ?? index + 1);
 134				const pointValue = Number(item[valueField] ?? 0);
 135				return {
 136					key: `${label}:${pointValue}:${index}`,
 137					label,
 138					sourceIndex: index,
 139					value: pointValue,
 140				};
 141			})
 142			.filter(
 143				(
 144					item,
 145				): item is {
 146					key: string;
 147					label: string;
 148					sourceIndex: number;
 149					value: number;
 150				} => Boolean(item && Number.isFinite(item.value)),
 151			);
 152	}
