 203	/** Keep agent-authored chart paint values inert. SVG `fill="url(...)"` can make
 204	 * a real network request even in an `allow-scripts` sandbox, so accept ordinary
 205	 * CSS colors only and fall back to the built-in palette for everything else. */
 206	function safeSvgPaint(value: unknown, fallback: string): string {
 207		if (typeof value !== "string") return fallback;
 208		const paint = value.trim();
 209		if (!paint || paint.length > 128 || /url\s*\(|[;{}<>@]/i.test(paint)) {
 210			return fallback;
 211		}
 212		if (/^#[\da-f]{3,8}$/i.test(paint)) return paint;
 213		if (/^(?:transparent|currentcolor|none|[a-z]+)$/i.test(paint)) return paint;
 214		if (
 215			/^(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch)\([-+.,%/\s\da-z]+\)$/i.test(paint)
 216		) {
 217			return paint;
 218		}
 219		return fallback;
 220	}
