 364	const PieChart: FC<{
 365		data: unknown;
 366		nameField?: string;
 367		valueField?: string;
 368		height?: number;
 369		showLabel?: boolean;
 370		showLegend?: boolean;
 371		radius?: string | [string, string];
 372		highlightName?: string | null;
 373	}> = ({
 374		data,
 375		nameField = "name",
 376		valueField = "value",
 377		height,
 378		showLabel = true,
 379		showLegend = true,
 380		radius = ["50%", "70%"],
 381		highlightName = null,
 382	}) => {
 383		const points = normalizePoints(data, nameField, valueField).filter(
 384			(point) => point.value > 0,
 385		);
 386		if (points.length === 0)
 387			return <p className="text-muted-foreground text-xs">No chart data.</p>;
 388		const total = points.reduce((sum, point) => sum + point.value, 0);
 389		const size = boundedDimension(height, 400, 140);
 390		const center = size / 2;
 391		const radiusValue = Array.isArray(radius) ? radius : ["0%", radius];
 392		const parseRadius = (value: string | undefined, fallback: number): number => {
 393			if (!value) return fallback;
 394			if (value.endsWith("%")) {
 395				const percentage = Number(value.slice(0, -1));
 396				return Number.isFinite(percentage)
 397					? (Math.max(0, Math.min(100, percentage)) / 100) * (center - 12)
 398					: fallback;
 399			}
 400			const numeric = Number(value);
 401			return Number.isFinite(numeric) ? Math.max(0, numeric) : fallback;
 402		};
 403		const innerRadius = parseRadius(String(radiusValue[0] ?? "0%"), 0);
 404		const outerRadius = Math.max(
 405			innerRadius + 1,
 406			parseRadius(String(radiusValue[1] ?? "70%"), center - 12),
 407		);
 408		const sourceItems = Array.isArray(data) ? data : [];
 409		const segmentPath = (start: number, end: number): string => {
 410			const safeEnd = end - start >= Math.PI * 2 ? end - 0.00001 : end;
 411			const outerStart = [
 412				center + outerRadius * Math.cos(start),
 413				center + outerRadius * Math.sin(start),
 414			];
 415			const outerEnd = [
 416				center + outerRadius * Math.cos(safeEnd),
 417				center + outerRadius * Math.sin(safeEnd),
 418			];
 419			const large = safeEnd - start > Math.PI ? 1 : 0;
 420			if (innerRadius <= 0) {
 421				return `M ${center} ${center} L ${outerStart[0]} ${outerStart[1]} A ${outerRadius} ${outerRadius} 0 ${large} 1 ${outerEnd[0]} ${outerEnd[1]} Z`;
 422			}
 423			const innerEnd = [
 424				center + innerRadius * Math.cos(safeEnd),
 425				center + innerRadius * Math.sin(safeEnd),
 426			];
 427			const innerStart = [
 428				center + innerRadius * Math.cos(start),
 429				center + innerRadius * Math.sin(start),
 430			];
 431			return `M ${outerStart[0]} ${outerStart[1]} A ${outerRadius} ${outerRadius} 0 ${large} 1 ${outerEnd[0]} ${outerEnd[1]} L ${innerEnd[0]} ${innerEnd[1]} A ${innerRadius} ${innerRadius} 0 ${large} 0 ${innerStart[0]} ${innerStart[1]} Z`;
 432		};
 433		let nextAngle = -Math.PI / 2;
 434		const segments = points.map((point, index) => {
 435			const start = nextAngle;
 436			nextAngle += (point.value / total) * Math.PI * 2;
 437			const item = sourceItems[point.sourceIndex];
 438			const sourceItem = isRecord(item) ? item : null;
 439			const itemStyle =
 440				sourceItem && isRecord(sourceItem.itemStyle)
 441					? sourceItem.itemStyle
 442					: null;
 443			return {
 444				...point,
 445				color:
 446					typeof itemStyle?.color === "string"
 447						? safeSvgPaint(
 448								itemStyle.color,
 449								CHART_COLORS[index % CHART_COLORS.length],
 450							)
 451						: CHART_COLORS[index % CHART_COLORS.length],
 452				end: nextAngle,
 453				opacity: highlightName && point.label !== highlightName ? 0.3 : 1,
 454				start,
 455			};
 456		});
 457		return (
 458			<div className="flex flex-wrap items-center gap-3">
 459				<svg
 460					viewBox={`0 0 ${size} ${size}`}
 461					width={size}
 462					height={size}
 463					className="max-w-full"
 464					role="img"
 465					aria-label="Pie chart"
 466				>
 467					<title>Pie chart</title>
 468					{segments.map((segment) => {
 469						const mid = segment.start + (segment.end - segment.start) / 2;
 470						const labelRadius = outerRadius + 12;
 471						return (
 472							<g key={segment.key}>
 473								<path
 474									d={segmentPath(segment.start, segment.end)}
 475									fill={segment.color}
 476									opacity={segment.opacity}
 477								>
 478									<title>{`${segment.label}: ${segment.value}`}</title>
 479								</path>
 480								{showLabel ? (
 481									<text
 482										x={center + labelRadius * Math.cos(mid)}
 483										y={center + labelRadius * Math.sin(mid)}
 484										textAnchor="middle"
 485										fontSize="10"
 486										fill="currentColor"
 487									>
 488										{segment.label}: {Math.round((segment.value / total) * 100)}%
 489									</text>
 490								) : null}
 491							</g>
 492						);
 493					})}
 494				</svg>
 495				{showLegend ? (
 496					<ul className="space-y-1 text-xs">
 497						{segments.map((segment) => (
 498							<li
 499								key={`${segment.key}:legend`}
 500								className="flex items-center gap-1.5"
 501							>
 502								<span
 503									className="h-2.5 w-2.5 rounded-sm"
 504									style={{
 505										backgroundColor: segment.color,
 506										opacity: segment.opacity,
 507									}}
 508								/>
 509								{segment.label}: {segment.value}
 510							</li>
 511						))}
 512					</ul>
 513				) : null}
 514			</div>
 515		);
 516	};
