 518	const Sparkline: FC<{
 519		data: unknown;
 520		color?: string;
 521		width?: number;
 522		height?: number;
 523		trend?: "up" | "down" | "stable";
 524	}> = ({ data, color = CHART_COLORS[0], width = 100, height = 40, trend }) => {
 525		const chartWidth = boundedDimension(width, 100, 20);
 526		const chartHeight = boundedDimension(height, 40, 16);
 527		const lineColor =
 528			trend === "up"
 529				? "#ef4444"
 530				: trend === "down"
 531					? "#22c55e"
 532					: safeSvgPaint(color, CHART_COLORS[0]);
 533		const values = Array.isArray(data)
 534			? data.map(Number).filter(Number.isFinite)
 535			: [];
 536		if (values.length === 0) values.push(0);
 537		const max = Math.max(...values);
 538		const min = Math.min(...values);
 539		const range = Math.max(max - min, 1);
 540		const points = values
 541			.map(
 542				(value, index) =>
 543					`${values.length > 1 ? (index / (values.length - 1)) * chartWidth : chartWidth / 2},${chartHeight - ((value - min) / range) * (chartHeight - 4) - 2}`,
 544			)
 545			.join(" ");
 546		const areaPoints = `${points} ${chartWidth},${chartHeight} 0,${chartHeight}`;
 547		return (
 548			<svg
 549				width={chartWidth}
 550				height={chartHeight}
 551				viewBox={`0 0 ${chartWidth} ${chartHeight}`}
 552				className="max-w-full overflow-visible"
 553				role="img"
 554				aria-label="Sparkline"
 555			>
 556				<title>Sparkline</title>
 557				<polygon points={areaPoints} fill={lineColor} fillOpacity="0.12" />
 558				<polyline
 559					points={points}
 560					fill="none"
 561					stroke={lineColor}
 562					strokeWidth="2"
 563					strokeLinecap="round"
 564					strokeLinejoin="round"
 565				/>
 566			</svg>
 567		);
