 856	function renderNode(
 857		node: McpJsonNode,
 858		context: RenderContext,
 859		key?: string | number,
 860	): ReactNode {
 861		if (!isRecord(node) || typeof node.type !== "string") return null;
 862		if (node.type === "text")
 863			return typeof node.content === "string" ? node.content : null;
 864		if (node.type === "data") {
 865			const value = getValueByPath(context.data, String(node.path ?? ""));
 866			const resolved = value === undefined ? node.fallback : value;
 867			return formatValue(resolved, node.format as ValueFormat | undefined);
 868		}
 869		if (node.type === "if") {
 870			const branch = getValueByPath(context.data, String(node.condition ?? ""))
 871				? node.then
 872				: node.else;
 873			return isRecord(branch)
 874				? renderNode(branch as McpJsonNode, context, key)
 875				: null;
 876		}
 877		if (node.type === "each") {
 878			const items = getValueByPath(context.data, String(node.items ?? ""));
 879			if (!Array.isArray(items)) return null;
 880			return items.map((item, index) => {
 881				const as = String(node.as ?? "item");
 882				const itemContext = {
 883					...context,
 884					data: { ...context.data, [as]: item, [`${as}Index`]: index },
 885				};
 886				if (typeof node.render === "string") {
 887					return (
 888						// biome-ignore lint/suspicious/noArrayIndexKey: template loop items may be duplicate, identity-less values and are immutable here.
 889						<span key={`${as}:${index}`}>
 890							{node.render.replaceAll(
 891								`{{${as}}}`,
 892								typeof item === "string" ? item : stringify(item),
 893							)}
 894						</span>
 895					);
 896				}
 897				return isRecord(node.render)
 898					? renderNode(node.render as McpJsonNode, itemContext, index)
 899					: null;
 900			});
 901		}
 902	
 903		const props = resolvedProps(node, context);
 904		const children = Array.isArray(node.children)
 905			? node.children.map((child, index) => renderNode(child, context, index))
 906			: undefined;
 907		const className =
 908			typeof props.className === "string" ? props.className : undefined;
