    20	// Map arbitrary object arrays to the {label, value} shape expected by bar/line/area charts.
    21	function normalizeLabelValueData(
    22	  data: unknown,
    23	  labelField?: string,
    24	  valueField?: string,
    25	): Array<{ label: string; value: number }> {
    26	  const arr = data as Array<Record<string, unknown>>;
    27	  if (!Array.isArray(arr)) return [];
    28	  if (!labelField && !valueField) return arr as Array<{ label: string; value: number }>;
    29	  return arr.map((d) => ({
    30	    label: String(d[labelField ?? 'label'] ?? ''),
    31	    value: Number(d[valueField ?? 'value'] ?? 0),
    32	  }));
    33	}
