   343	
   344	function renderCellValue(col: string, value: unknown): React.ReactNode {
   345	  if (value == null) return <span className="text-muted-foreground">–</span>;
   346	
   347	  const str = String(value);
   348	
   349	  // URL fields or values that look like URLs
   350	  if (str.startsWith('http://') || str.startsWith('https://')) {
   351	    return (
   352	      <a
   353	        href={str}
   354	        target="_blank"
   355	        rel="noopener noreferrer"
   356	        className="text-primary hover:underline"
   357	      >
   358	        {col === 'url' ? '↗ Link' : str}
   359	      </a>
   360	    );
   361	  }
   362	
   363	  // Subreddit → link to reddit
   364	  if (col === 'subreddit' && typeof value === 'string') {
   365	    return (
   366	      <a
   367	        href={`https://reddit.com/r/${value}`}
   368	        target="_blank"
   369	        rel="noopener noreferrer"
   370	        className="text-primary hover:underline"
   371	      >
   372	        r/{value}
   373	      </a>
   374	    );
   375	  }
   376	
   377	  // Badge fields (urgency, severity, etc.)
   378	  if (BADGE_FIELDS.has(col) && typeof value === 'string') {
   379	    const style =
   380	      URGENCY_STYLES[value.toLowerCase()] ?? 'bg-secondary text-secondary-foreground border-border';
   381	    const humanized = value.replace(/[_-]/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
   382	    return (
