   186	function walkHandlers(node: unknown, path: string): void {
   187		if (!isPlainObject(node)) return;
   188		if (node.type === "if") {
   189			walkHandlers(node.then, `${path}.then`);
   190			if (node.else !== undefined) walkHandlers(node.else, `${path}.else`);
   191			return;
   192		}
   193		if (node.type === "each") {
   194			if (typeof node.render !== "string") {
   195				walkHandlers(node.render, `${path}.render`);
   196			}
   197			return;
   198		}
   199		if (node.type === "text" || node.type === "data") return;
